class Shape:
    def __init__(self, color):
        self.color = color

class Circle(Shape):
    def __init__(self, color, radius):
        super().__init__(color)
        self.radius = radius

    def area(self):
        return 3.14159 * self.radius ** 2

class Square(Shape):
    def __init__(self, color, side):
        super().__init__(color)
        self.side = side

    def area(self):
        return self.side ** 2

def print_area(shape):
    if not isinstance(shape, Shape):
        print('Not a shape')
    else:
        print(f'Area of {shape.color} shape: {shape.area():.2f}')

# 示例调用
c = Circle('red', 3.0)
s = Square('blue', 4.0)
print_area(c)
print_area(s)
